begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions, pg_catalog;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values ('00000000-0000-0000-0000-000000000041','content-policy@example.invalid','{"requested_username":"PolicyOwner"}');
select throws_ok($$insert into auth.users(id,email,raw_user_meta_data) values ('00000000-0000-0000-0000-000000000042','blocked-policy@example.invalid','{"requested_username":"sh1t"}')$$, 'P0001', 'Username: choose a name without profanity.', 'email signup still filters usernames');
select ok(not exists(select 1 from auth.users where id='00000000-0000-0000-0000-000000000042'), 'a rejected signup leaves no partial user');
select ok(not has_function_privilege('authenticated','app_private.content_reason(text,text)','execute'), 'policy helpers stay private');
select ok(not has_function_privilege('anon','app_private.assert_content(text,text,text)','execute'), 'guests cannot execute private helpers');
update public.profiles set username_changed_at=now()-interval '4 months', username_change_available_at=now()-interval '1 month' where id='00000000-0000-0000-0000-000000000041';
set local role authenticated;
select set_config('request.jwt.claims', '{"sub":"00000000-0000-0000-0000-000000000041","role":"authenticated"}', true);
select throws_ok($$select public.set_username('Damn')$$, 'P0001', 'Username: choose a name without profanity.', 'username filters remain strict');
select is((select display_name from public.profiles), 'PolicyOwner', 'rejected rename preserves profile');
select ok((select username_change_available_at < now() from public.profiles), 'rejected rename does not consume cooldown');
select lives_ok($$select public.set_username('Scunthorpe')$$, 'innocent words remain valid usernames');
select lives_ok($$select public.save_bracket_draft('10000000-0000-0000-0000-000000000041',0,'A shit showdown','hardcore sex','movies-tv','crown','private','{"mode":"manual"}',array['Any fucking movie','Unlisted shit movie'])$$, 'non-slur language and unlisted titles are allowed in private brackets');
select lives_ok($$select public.save_bracket_draft('10000000-0000-0000-0000-000000000043',0,'Another shit showdown','hardcore sex','movies-tv','crown','public','{"mode":"end-date"}',array['Any fucking movie','Unlisted shit movie'])$$, 'public brackets also have only the slur check');
select is((select name from public.bracket_entries where bracket_id='10000000-0000-0000-0000-000000000041' and seed=1), 'Any fucking movie', 'accepted words are not censored or rewritten');
select throws_ok($$select public.save_bracket_draft('10000000-0000-0000-0000-000000000042',0,'A nigger showdown','','movies-tv','crown','private','{"mode":"manual"}',array['Alpha','Beta'])$$, 'P0001', 'Bracket name: remove slurs.', 'private bracket titles reject slurs');
select throws_ok($$select public.save_bracket_draft('10000000-0000-0000-0000-000000000042',0,'A nigger showdown','','movies-tv','crown','public','{"mode":"end-date"}',array['Alpha','Beta'])$$, 'P0001', 'Bracket name: remove slurs.', 'public bracket titles reject slurs');
select throws_ok($$select public.save_bracket_draft('10000000-0000-0000-0000-000000000041',1,'Changed title','n1gg3r','movies-tv','crown','private','{"mode":"manual"}',array['Alpha','Beta'])$$, 'P0001', 'Description: remove slurs.', 'descriptions reject obfuscated slurs');
select throws_ok($$select public.save_bracket_draft('10000000-0000-0000-0000-000000000041',1,'Changed title','','movies-tv','crown','private','{"mode":"manual"}',array['Alpha','n i g g e r'])$$, 'P0001', 'Competitor 2: remove slurs.', 'competitor error identifies the field');
select is((select title from public.brackets where id='10000000-0000-0000-0000-000000000041'), 'A shit showdown', 'rejected save preserves the old title');
select is((select revision from public.brackets where id='10000000-0000-0000-0000-000000000041'), 1::bigint, 'rejected save preserves revision');
select is((select name from public.bracket_entries where bracket_id='10000000-0000-0000-0000-000000000041' and seed=2), 'Unlisted shit movie', 'rejected replacement preserves the competitor list');
select is((select count(*) from public.brackets where id='10000000-0000-0000-0000-000000000042'), 0::bigint, 'rejected new bracket leaves no partial draft');
reset role;
select * from finish();
rollback;
